#### Tầng A — Hàm PostgreSQL RPC có Khóa Dòng `FOR UPDATE` chống rút tiền đúp (Race Condition Lock):
```sql
CREATE OR REPLACE FUNCTION process_wallet_purchase(
  p_user_id UUID,
  p_product_id TEXT,
  p_amount NUMERIC
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_wallet RECORD;
  v_new_balance NUMERIC;
BEGIN
  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Số tiền giao dịch không hợp lệ');
  END IF;

  -- Khóa dòng vật lý ví của người dùng, chặn đứng 100% Race Condition (bắn 100 request cùng lúc)
  SELECT * INTO v_wallet
  FROM public.wallets
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Không tìm thấy ví người dùng');
  END IF;

  IF v_wallet.balance < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Số dư ví không đủ để thanh toán');
  END IF;

  -- Trừ tiền nguyên tử (Atomic Deduction)
  v_new_balance := v_wallet.balance - p_amount;
  UPDATE public.wallets
  SET balance = v_new_balance, updated_at = NOW()
  WHERE user_id = p_user_id;

  -- Ghi nhận lịch sử giao dịch bất biến (Immutable Audit Log)
  INSERT INTO public.wallet_transactions (user_id, product_id, amount, balance_after, type, created_at)
  VALUES (p_user_id, p_product_id, -p_amount, v_new_balance, 'PURCHASE', NOW());

  RETURN jsonb_build_object('success', true, 'new_balance', v_new_balance);
END;
$$;
```

#### Tầng B — Module Niêm Phong Chữ Ký Số `computeWalletSeal` & Đấu Nối Backend (BẮT BUỘC ĐI KÈM):
```javascript
import crypto from 'node:crypto';

// 1. Tạo và kiểm tra chữ ký HMAC-SHA256 chống F12 DevTools sửa số dư hoặc giả mạo request
export function computeWalletSeal(userId, balance, secret = process.env.WALLET_HMAC_SECRET) {
  return crypto
    .createHmac('sha256', String(secret))
    .update(`${userId}:${Number(balance).toFixed(0)}`)
    .digest('hex');
}

export function verifyWalletSeal(userId, balance, clientSeal, secret = process.env.WALLET_HMAC_SECRET) {
  const expected = computeWalletSeal(userId, balance, secret);
  return crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(String(clientSeal || '')));
}

// 2. Hàm Backend gọi thẳng RPC Database (Tuyệt đối lấy giá sản phẩm từ Server, không nhận giá từ Client)
export async function executeSecurePurchase(supabaseAdmin, { userId, productId }) {
  const { data: product, error: prodErr } = await supabaseAdmin
    .from('products')
    .select('id, price, stock')
    .eq('id', productId)
    .single();

  if (prodErr || !product) throw new Error('Sản phẩm không tồn tại!');

  const { data: rpcResult, error: rpcErr } = await supabaseAdmin.rpc('process_wallet_purchase', {
    p_user_id: userId,
    p_product_id: product.id,
    p_amount: product.price
  });

  if (rpcErr || !rpcResult?.success) {
    throw new Error(rpcResult?.error || rpcErr?.message || 'Giao dịch thất bại');
  }

  return {
    success: true,
    newBalance: rpcResult.new_balance,
    walletSeal: computeWalletSeal(userId, rpcResult.new_balance)
  };
}
```

