---

### QUY TẮC 1: BỘ TỔNG HỢP 6 HIỆU ỨNG ÂM THANH 0MB CHUẨN STUDIO (`WebAudioSynthStudio`)
Mọi hiệu ứng âm thanh phải tuân thủ đường bao sinh học ADSR (Attack - Decay - Sustain - Release) dùng `exponentialRampToValueAtTime` để âm thanh trong trẻo, ấm áp, tuyệt đối không bị tiếng nổ lụp bụp (audio clipping):

```javascript
/**
 * Bùi Thái AI Studio — WebAudioSynthStudio v12.0 (0MB Download | <1ms Latency | Auto-Wired)
 */
const WebAudioSynthStudio = {
  ctx: null,
  muted: false,

  // Khởi tạo và tự động mở khóa AudioContext khi bị trình duyệt tạm dừng (suspended)
  init() {
    if (this.muted || typeof window === 'undefined') return null;
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) this.ctx = new AudioCtx();
    }
    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume().catch(() => {});
    }
    return this.ctx;
  },

  // 1. Tiếng bấm nút xúc giác Apple Taptic Engine (140Hz -> 40Hz trong 40ms)
  playTapticClick() {
    const ctx = this.init();
    if (!ctx) return;
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(140, now);
    osc.frequency.exponentialRampToValueAtTime(40, now + 0.04);
    gain.gain.setValueAtTime(0.22, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.04);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 0.045);
  },

  // 2. Tiếng rơi đồng Xu vàng lấp lánh (B5 987.77Hz -> E6 1318.51Hz)
  playCoinDrop() {
    const ctx = this.init();
    if (!ctx) return;
    const now = ctx.currentTime;
    [987.77, 1318.51].forEach((freq, idx) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      const start = now + idx * 0.075;
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, start);
      gain.gain.setValueAtTime(0.18, start);
      gain.gain.exponentialRampToValueAtTime(0.001, start + 0.35);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(start);
      osc.stop(start + 0.36);
    });
  },

  // 3. Tiếng chuông giao dịch / mở khóa thành công (Hợp âm C5 - E5 - G5 - C6)
  playSuccessChime() {
    const ctx = this.init();
    if (!ctx) return;
    const now = ctx.currentTime;
    [523.25, 659.25, 783.99, 1046.50].forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      const start = now + i * 0.08;
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(freq, start);
      gain.gain.setValueAtTime(0.15, start);
      gain.gain.exponentialRampToValueAtTime(0.001, start + 0.38);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(start);
      osc.stop(start + 0.40);
    });
  },

  // 4. Tiếng cảnh báo lỗi / nhập sai mật khẩu (Rung trầm 150Hz -> 110Hz)
  playErrorBuzz() {
    const ctx = this.init();
    if (!ctx) return;
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(150, now);
    osc.frequency.setValueAtTime(110, now + 0.09);
    gain.gain.setValueAtTime(0.14, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.24);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 0.25);
  },

  // 5. Tiếng mở hộp mù Gacha / Vòng quay may mắn (Arpeggio tăng tốc)
  playGachaReveal() {
    const ctx = this.init();
    if (!ctx) return;
    const now = ctx.currentTime;
    const scale = [392.00, 440.00, 493.88, 523.25, 587.33, 659.25, 783.99, 1046.50];
    scale.forEach((freq, idx) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      const start = now + idx * 0.055;
      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, start);
      gain.gain.setValueAtTime(0.14, start);
      gain.gain.exponentialRampToValueAtTime(0.001, start + 0.25);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(start);
      osc.stop(start + 0.26);
    });
  },

  // 6. Tự động gắn kết sự kiện âm thanh vào toàn bộ trang web (Auto-Wiring Engine)
  mountAutoSoundEvents() {
    if (typeof window === 'undefined' || this._mounted) return;
    this._mounted = true;

    // Mở khóa AudioContext ngay ở thao tác chạm đầu tiên trên iOS/Android/Desktop
    ['pointerdown', 'keydown', 'touchstart'].forEach(evt => {
      window.addEventListener(evt, () => this.init(), { once: true, passive: true });
    });

    // Tự động phát tiếng dựa trên thuộc tính data-sound hoặc loại phần tử bấm
    document.addEventListener('click', (e) => {
      const customSoundEl = e.target.closest('[data-sound]');
      if (customSoundEl) {
        const type = customSoundEl.getAttribute('data-sound');
        if (type === 'coin') return this.playCoinDrop();
        if (type === 'success') return this.playSuccessChime();
        if (type === 'error') return this.playErrorBuzz();
        if (type === 'gacha') return this.playGachaReveal();
