/**
 * Động cơ Quay Hộp Mù Gacha Có Bảo Hiểm Pity (Anti-Frustration RNG Engine)
 */
const GachaTokenomicsEngine = {
  TIERS: [
    { id: 'LEGENDARY', name: 'Huyền Thoại (Master Vault)', weight: 1,  minMultiplier: 2.5 },
    { id: 'EPIC',      name: 'Sử Thi (Flagship Toolkit)',  weight: 7,  minMultiplier: 1.5 },
    { id: 'RARE',      name: 'Hiếm (Pro Skill Pack)',      weight: 22, minMultiplier: 1.1 },
    { id: 'COMMON',    name: 'Phổ Thông (Voucher & Xu)',   weight: 70, minMultiplier: 0.8 }
  ],
  PITY_LIMIT: 10, // Chắc chắn nổ Sử Thi hoặc Huyền Thoại ở lượt thứ 10

  rollBlindBox(userPityCount = 0) {
    const nextPity = Number(userPityCount) + 1;

    // Kích hoạt Bảo Hiểm Pity ở lượt thứ 10
    if (nextPity >= this.PITY_LIMIT) {
      const isLegendary = Math.random() < 0.20; // 20% lên thẳng Huyền Thoại, 80% Sử Thi
      const tier = isLegendary ? this.TIERS[0] : this.TIERS[1];
      return { tier, newPityCount: 0, isPityTriggered: true };
    }

    // Quay ngẫu nhiên theo trọng số (Weighted Random)
    const totalWeight = this.TIERS.reduce((sum, t) => sum + t.weight, 0);
    let rand = Math.random() * totalWeight;
    for (const tier of this.TIERS) {
      if (rand < tier.weight) {
        const resetPity = (tier.id === 'LEGENDARY' || tier.id === 'EPIC');
        return {
          tier,
          newPityCount: resetPity ? 0 : nextPity,
          isPityTriggered: false
        };
      }
      rand -= tier.weight;
    }
    return { tier: this.TIERS[3], newPityCount: nextPity, isPityTriggered: false };
  }
};
